<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'; import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue'; import { HostEvent, HostSurface } from '../../platform/host-adapter.mjs'; import { createInteractionsApi, InteractionsApiError } from './domain/interactions-api.mjs'; import { interactionsListViewModel } from './domain/interactions-view.mjs'; import InteractionsListDesktop from './desktop/InteractionsListDesktop.vue'; import InteractionsListMobile from './mobile/InteractionsListMobile.vue';
const props = defineProps({ surface: { type: String, required: true }, adapter: { type: Object, default: null }, hostUnavailable: { type: Boolean, default: false } }); const emit = defineEmits(['back']); const api = createInteractionsApi(); const state = reactive({ phase: 'loading', rows: [], total: 0, page: 1, pageSize: 20, search: '', error: null }); const safeArea = ref(props.adapter?.getSafeArea?.() || {}); const unsubscribers = []; const isNative = computed(() => props.surface === HostSurface.NATIVE); const safeAreaStyle = computed(() => Object.fromEntries(['top', 'right', 'bottom', 'left'].flatMap((side) => Number.isFinite(Number(safeArea.value?.[side])) ? [[`--mds-mobile-safe-${side}`, `${Number(safeArea.value[side])}px`]] : [])));
function setError(error) { state.error = error instanceof InteractionsApiError ? error : new InteractionsApiError({ status: 0, code: 'INTERACTIONS_NETWORK', message: 'Không thể tải tương tác. Vui lòng thử lại.' }); state.phase = 'error'; }
async function load({ page = state.page, search = state.search } = {}) { if (props.hostUnavailable) { setError(new InteractionsApiError({ status: 503, code: 'HOST_ADAPTER_UNAVAILABLE', message: 'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.' })); return; } state.phase = 'loading'; state.error = null; try { const model = interactionsListViewModel(await api.getList({ page, pageSize: state.pageSize, search })); state.rows = model.rows; state.total = model.total; state.page = model.page; state.pageSize = model.pageSize; state.search = search; state.phase = 'ready'; } catch (error) { setError(error); } }
function search(value) { load({ page: 1, search: value }); } function changePage(page) { load({ page, search: state.search }); } async function goBack() { if (isNative.value && props.adapter) { await props.adapter.goBack({ reason: 'interactions-list' }); return; } emit('back'); } function listen() { if (!props.adapter || props.hostUnavailable) return; unsubscribers.push(props.adapter.subscribe(HostEvent.VIEWPORT, (payload) => { if (payload?.safeArea) safeArea.value = { ...safeArea.value, ...payload.safeArea }; })); unsubscribers.push(props.adapter.subscribe(HostEvent.LIFECYCLE, (payload) => { if (payload?.state === 'foreground') load(); })); } onMounted(() => { listen(); load(); }); onBeforeUnmount(() => { while (unsubscribers.length) unsubscribers.pop()(); });
</script>
<template><div v-if="state.phase === 'loading'" :class="isNative ? 'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]' : 'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'" :style="isNative ? safeAreaStyle : undefined"><MSpinner :size="28" class="text-[var(--mds-brand-600)]" /></div><section v-else-if="state.phase === 'error'" :class="isNative ? 'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]' : 'min-h-[360px] bg-[var(--mds-bg-page)]'" :style="isNative ? safeAreaStyle : undefined"><MMobileTopBar v-if="isNative" title="Lịch sử tương tác" @back="goBack" /><MEmptyState :title="state.error.status === 403 ? 'Bạn không có quyền xem tương tác' : 'Không thể mở tương tác'" :description="state.error.message" /></section><InteractionsListMobile v-else-if="isNative" :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :loading="false" :safe-area-style="safeAreaStyle" @back="goBack" @search="search" @page="changePage" /><InteractionsListDesktop v-else :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :loading="false" @search="search" @page="changePage" /></template>
